<script setup>import { onMounted, ref } from "vue"; import AdminLayout from "../../layouts/AdminLayout.vue"; import { materialService, requestService, userService } from "../../services/api"; const stats = ref([]), error = ref(""); onMounted(async () => { try { const [users, materials, requests] = await Promise.all([userService.pending(), materialService.list(), requestService.pending()]); const list = materials.data; stats.value = [["Utilisateurs en attente", users.data.length, "👥", "/admin/utilisateurs"], ["Matériels disponibles", list.reduce((sum, item) => sum + item.quantite_disponible, 0), "💻", "/admin/materiels"], ["Demandes en attente", requests.data.length, "📋", "/admin/demandes"], ["Matériels empruntés", list.reduce((sum, item) => sum + item.quantite_totale - item.quantite_disponible, 0), "↗", "/admin/materiels"]]; } catch (exception) { error.value = exception.message; } });</script><template><AdminLayout><section class="p-5 md:p-10"><p class="text-sm font-semibold uppercase tracking-widest text-[#3f7452]">Administration</p><h1 class="mt-2 text-3xl font-bold">Tableau de bord</h1><div v-if="error" class="alert alert-error mt-6">{{ error }}</div><div v-else class="mt-7 grid gap-5 sm:grid-cols-2 xl:grid-cols-4"><RouterLink v-for="stat in stats" :key="stat[0]" :to="stat[3]" class="group rounded-2xl border border-slate-100 bg-white p-5 shadow-sm transition hover:-translate-y-1 hover:border-green-200 hover:shadow-lg"><span class="text-2xl">{{ stat[2] }}</span><p class="mt-5 text-3xl font-bold text-slate-800">{{ stat[1] }}</p><p class="mt-1 text-sm text-slate-500">{{ stat[0] }}</p><p class="mt-4 text-xs font-semibold text-[#17482d] opacity-0 transition group-hover:opacity-100">Voir le détail →</p></RouterLink></div><p class="mt-8 text-sm text-slate-400">Les indicateurs sont calculés à partir des endpoints actuellement disponibles.</p></section></AdminLayout></template>
